/* Generated by the module split. See README §開発の分担. */
import * as THREE from 'three';
import { C } from './palette.js';
import { byId, ST } from './layout.js';
import { S, GAME, model, KERNEL_PASS, MATCH_RATE, SET_MUL, hasCap } from './state.js';
import { RING_LANES, OUT_PIPES } from './districts.build.js';
import { scene } from './scene.js';
import { emitLog, onDrop } from './log.js';


/* ============================================================
   8. event particle simulation
   ============================================================ */
/* stage boundaries live in ST, derived from the layout (see section 1b) */

const N = 1400;
const pos = new Float32Array(N*3);
const col = new Float32Array(N*3);
const siz = new Float32Array(N);
const alp = new Float32Array(N);

const P = new Array(N);
const tmpC = new THREE.Color();

function setCol(i, hex, mul=1){
  tmpC.setHex(hex);
  col[i*3]=tmpC.r*mul; col[i*3+1]=tmpC.g*mul; col[i*3+2]=tmpC.b*mul;
}

function spawn(i, delay=0){
  const p = P[i] || (P[i]={});
  p.x = ST.start - Math.random()*10;
  p.z0 = (Math.random()-0.5)*30;
  p.z = p.z0;
  p.y = 3 + Math.random()*7;
  p.sp = 26 + Math.random()*20;
  p.st = 0;                     // 0 raw · 1 dropping · 2 matched · 3 dying
  p.lane = RING_LANES.length ? RING_LANES[(Math.random()*RING_LANES.length)|0] : 0;
  p.delay = S.dead ? 1e9 : delay;   // agent stopped → nothing new enters the pipeline
  p.fade = 1;
  p.prio = 0;
  /* per-pass gates — MUST be reset, particles are recycled */
  p.gated = false; p.dropRolled = false; p.enriched = false; p.rolled = false;
  /* with no kernel path there is nothing to carry a syscall up, so every event
     that arrives came in through a plugin. Read the declared attribute rather
     than the topology's name — the name stops being the reason as soon as a
     second topology shares it. */
  const pluginsUp = !GAME.on || GAME.built.has('plugins');
  p.plugin = pluginsUp && (!hasCap('kernelPath') || Math.random() < 0.03);
  if(p.plugin){
    p.x = ST.pluginX; p.z0 = ST.pluginZ + (Math.random()-0.5)*16; p.z = p.z0; p.y = 6;
    /* plugin inputs bypass driver + ring buffer entirely */
    p.gated = true; p.dropRolled = true; p.enriched = true;
  }
  siz[i] = p.plugin ? 1.5 : 1.15 + Math.random()*0.5;
  alp[i] = 0;
  setCol(i, p.plugin ? C.orange : C.g25);
  return p;
}
for(let i=0;i<N;i++) spawn(i, Math.random()*4);

const pg = new THREE.BufferGeometry();
pg.setAttribute('position', new THREE.BufferAttribute(pos,3));
pg.setAttribute('pcolor',   new THREE.BufferAttribute(col,3));
pg.setAttribute('size',     new THREE.BufferAttribute(siz,1));
pg.setAttribute('alpha',    new THREE.BufferAttribute(alp,1));

const pMat = new THREE.ShaderMaterial({
  transparent:true, depthWrite:false,
  vertexShader:`
    attribute float size; attribute float alpha; attribute vec3 pcolor;
    varying vec3 vC; varying float vA;
    void main(){
      vC=pcolor; vA=alpha;
      vec4 mv = modelViewMatrix * vec4(position,1.0);
      gl_PointSize = size * (620.0 / -mv.z);
      gl_Position = projectionMatrix * mv;
    }`,
  fragmentShader:`
    varying vec3 vC; varying float vA;
    void main(){
      vec2 c = gl_PointCoord - 0.5;
      float d = dot(c,c);
      if(d > 0.25) discard;
      float e = smoothstep(0.25, 0.14, d);
      gl_FragColor = vec4(vC, vA * e);
    }`
});
const points = new THREE.Points(pg, pMat);
points.frustumCulled = false;
scene.add(points);

/* --- policy downlink particles (Sysdig → rules/driver) --- */
const PN = 200;
const ppos = new Float32Array(PN*3), palp = new Float32Array(PN);
const PP = [];
/* Where rules come from. In OSS that is falcoctl pulling OCI artifacts; with
   Sysdig it is managed policies descending from the backend. Same stream,
   different source — which is exactly the point being made. */
function spawnPolicy(i){
  const sysdigMode = S.mode === 'sysdig';
  const src = byId(sysdigMode ? 'sysdig' : 'falcoctl');
  const ru  = byId('rules'), dr = byId('driver');
  /* only the Sysdig side also pushes config down to the driver */
  const toRules = sysdigMode ? Math.random() < 0.6 : true;
  PP[i] = {
    t: -Math.random()*2,
    sp: 0.28 + Math.random()*0.2,
    a: [src.cx - 4, src.y + (sysdigMode ? 0 : 7), src.cz],
    b: toRules
      ? [ru.cx + (Math.random()-0.5)*16, ru.top + 1, ru.cz + (Math.random()-0.5)*20]
      : [dr.cx + (Math.random()-0.5)*8,  dr.top,     (Math.random()-0.5)*30]
  };
  palp[i]=0;
}
for(let i=0;i<PN;i++) spawnPolicy(i);
const polGeo = new THREE.BufferGeometry();
polGeo.setAttribute('position', new THREE.BufferAttribute(ppos,3));
polGeo.setAttribute('alpha', new THREE.BufferAttribute(palp,1));
const polMat = new THREE.ShaderMaterial({
  transparent:true, depthWrite:false,
  uniforms:{ uColor:{value:new THREE.Color(C.lumin)} },
  vertexShader:`
    attribute float alpha; varying float vA;
    void main(){ vA=alpha;
      vec4 mv=modelViewMatrix*vec4(position,1.0);
      gl_PointSize = 2.0*(620.0/-mv.z);
      gl_Position=projectionMatrix*mv; }`,
  fragmentShader:`
    uniform vec3 uColor; varying float vA;
    void main(){ vec2 c=gl_PointCoord-0.5; if(dot(c,c)>0.25) discard;
      gl_FragColor=vec4(uColor, vA*0.9); }`
});
const polPoints = new THREE.Points(polGeo, polMat);
polPoints.frustumCulled = false; scene.add(polPoints);



/* ============================================================
   9. simulation step
   ============================================================ */
function step(dt){
  const load = S.load;
  const M = model();
  const dropP = S.dead ? 0 : M.dropP;
  const drvMul = S.driver==='modern_ebpf' ? 1 : (S.driver==='ebpf' ? 0.92 : 0.84);

  for(let i=0;i<N;i++){
    const p = P[i];
    if(p.delay > 0){ p.delay -= dt; alp[i]=0; continue; }

    const speed = p.sp * (0.55 + load*0.6) * drvMul;

    /* --- plugin bypass lane: straight to the rules engine --- */
    if(p.plugin && p.st===0){
      p.x += speed*dt*0.8;
      if(p.x > ST.state-30) p.z += (ST.joinZ - p.z)*Math.min(1,dt*1.1);
      p.y += ((6) - p.y)*Math.min(1,dt*2);
      alp[i] = 0.85;
      if(p.x >= ST.rulesIn) p.plugin = false;   // joins the main match logic
      writeP(i,p); continue;
    }

    switch(p.st){
      case 0: {
        p.x += speed*dt;
        if(GAME.on && p.x > GAME.frontier){ p.st=3; p.fade=1; writeP(i,p); break; }

        /* kernel gate */
        if(p.gated !== true && p.x >= ST.driver){
          p.gated = true;
          S.counters.sys++;
          /* base_syscalls decides how much the driver forwards at all */
          if(Math.random() > M.passRatio){ p.st=3; p.fade=1; }   // not in the syscall set
          else { S.counters.ring++; setCol(i, C.falco, 0.62); }
        }

        /* ring buffer: snap into a per-CPU lane */
        if(p.x > ST.ringIn && p.x < ST.ringOut){
          p.z += (p.lane - p.z) * Math.min(1, dt*4.2);
          p.y += (2.6 - p.y) * Math.min(1, dt*4.2);
          if(p.dropRolled !== true){
            p.dropRolled = true;
            if(Math.random() < dropP){
              p.st = 1; p.fade = 1;
              S.counters.drop++;
              onDrop();
              setCol(i, C.redUi);
            }
          }
        }

        /* leaving the buffer → enrichment */
        if(p.x > ST.ringOut && p.x < ST.state+8){
          p.z += (p.z0*0.6 - p.z) * Math.min(1, dt*1.6);
          p.y += (5.5 - p.y) * Math.min(1, dt*2.2);
          if(p.enriched !== true && p.x > ST.state){
            p.enriched = true;
            setCol(i, C.falco);
            siz[i] *= 1.25;
          }
        }

        /* rules engine */
        if(p.x >= ST.rulesIn && p.rolled !== true){
          p.rolled = true;
          S.counters.rules++;
          if(Math.random() < MATCH_RATE){
            p.st = 2;
            p.prio = pickPriority();
            setCol(i, PRIO[p.prio].hex);
            siz[i] = 3.1;
            S.counters.alerts++;
            S.alertWindow.push(performance.now());
            emitLog(p.prio);
          } else {
            p.st = 3; p.fade = 1;               // no match → evaporates
          }
        }
        alp[i] = p.x < ST.driver ? 0.5 : 0.85;
        break;
      }
      case 1: {                                 // dropped
        p.x += speed*dt*0.35;
        p.z += 17*dt;
        p.y -= 7*dt;
        p.fade -= dt*1.5;
        alp[i] = Math.max(0, p.fade)*0.95;
        if(p.fade <= 0) spawn(i, Math.random()*1.2);
        break;
      }
      case 2: {                                 // matched alert
        p.x += speed*dt*0.85;
        if(GAME.on && p.x > GAME.frontier && !GAME.built.has('sysdig')){
          p.st=3; p.fade=1; writeP(i,p); break;
        }
        if(p.x > ST.rulesOut && p.x < ST.out+8){
          const tz = OUT_PIPES.length ? OUT_PIPES[p.prio % OUT_PIPES.length] : 0;
          p.z += (tz - p.z)*Math.min(1,dt*2.4);
          p.y += (3.4 - p.y)*Math.min(1,dt*2.4);
        }
        if(S.mode==='sysdig' && p.x > ST.out+4){
          // climb to the platform
          p.z += (ST.skyZ - p.z)*Math.min(1,dt*0.85);
          p.y += (ST.skyY+2 - p.y)*Math.min(1,dt*1.05);
          p.x += (ST.skyX - p.x)*Math.min(1,dt*0.5);
          if(p.y > ST.skyY && Math.abs(p.x-ST.skyX) < 6){ p.st=3; p.fade=1; }
        } else if(p.x > ST.end){ p.st=3; p.fade=1; }
        alp[i]=0.98;
        break;
      }
      case 3: {                                 // fading out
        p.x += speed*dt*0.25;
        p.fade -= dt*2.6;
        alp[i] = Math.max(0, p.fade)*0.6;
        if(p.fade <= 0) spawn(i, Math.random()*(1.4/Math.max(0.3,load)));
        break;
      }
    }
    writeP(i,p);
  }
  pg.attributes.position.needsUpdate = true;
  pg.attributes.pcolor.needsUpdate = true;
  pg.attributes.alpha.needsUpdate = true;
  pg.attributes.size.needsUpdate = true;

  /* rule / policy stream — always running, only the source differs */
  const showPolicy = true;
  polPoints.visible = showPolicy;
  if(showPolicy){
    for(let i=0;i<PN;i++){
      const q = PP[i];
      q.t += q.sp*dt;
      if(q.t > 1.15){ spawnPolicy(i); continue; }
      const t = Math.max(0,q.t);
      const e = t*t*(3-2*t);
      ppos[i*3]   = q.a[0]+(q.b[0]-q.a[0])*e;
      ppos[i*3+1] = q.a[1]+(q.b[1]-q.a[1])*e + Math.sin(t*Math.PI)*4;
      ppos[i*3+2] = q.a[2]+(q.b[2]-q.a[2])*e;
      palp[i] = q.t < 0 ? 0 : Math.sin(Math.min(1,t)*Math.PI)*0.95;
    }
    polGeo.attributes.position.needsUpdate = true;
    polGeo.attributes.alpha.needsUpdate = true;
  }
}
function writeP(i,p){ pos[i*3]=p.x; pos[i*3+1]=p.y; pos[i*3+2]=p.z; }

const PRIO = [
  {name:'Critical', cls:'p-crit', hex:C.purple},
  {name:'Error',    cls:'p-err',  hex:C.redUi},
  {name:'Warning',  cls:'p-warn', hex:C.orange},
  {name:'Notice',   cls:'p-note', hex:C.falco}
];
function pickPriority(){
  const r = Math.random();
  return r<0.10 ? 0 : r<0.32 ? 1 : r<0.74 ? 2 : 3;
}

export {
  N,
  P,
  pos,
  alp,
  siz,
  points,
  polPoints,
  polMat,
  PN,
  spawn,
  spawnPolicy,
  step,
  writeP,
  PRIO,
  pickPriority
};
